curl -s -X POST https://slack.com/api/users.list \
  -d token=<TOKEN> \
  -d limit=200 | python3 -c "
import json,sys
data = json.load(sys.stdin)
if data.get('ok'):
    for m in data['members']:
        name = m.get('real_name','') or m.get('profile',{}).get('real_name','')
        if 'robert' in name.lower() or 'robert' in m.get('name','').lower():
            print(m['id'], m.get('name'), name, 'is_admin:', m.get('is_admin'), 'is_owner:', m.get('is_owner'))
else:
    print(data)
"

